# aplicar-v73-forcar-orders-e-financeiro-separados.ps1
# Corrige de vez:
# /admin/orders  = tela de pedidos
# /admin/finance = tela financeira separada
#
# O script preserva a tela financeira atual, se ela estiver por engano em /admin/orders,
# copiando-a para /admin/finance antes de sobrescrever /admin/orders.

$ErrorActionPreference = "Stop"

$Root = Get-Location
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"

$OrdersPath = Join-Path $Root "apps\web\src\app\admin\orders\page.tsx"
$FinancePath = Join-Path $Root "apps\web\src\app\admin\finance\page.tsx"
$FinanceDir = Split-Path $FinancePath -Parent
$HeaderPath = Join-Path $Root "apps\web\src\components\customer\CustomerHeader.tsx"

function Write-Utf8FileFromBase64($Path, $Base64Content) {
  $Dir = Split-Path $Path -Parent

  if (-not (Test-Path $Dir)) {
    New-Item -ItemType Directory -Path $Dir -Force | Out-Null
  }

  if (Test-Path $Path) {
    $Backup = "$Path.bak-v73-$Stamp"
    Copy-Item $Path $Backup -Force
    Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray
  }

  $Content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64Content))
  Set-Content -Path $Path -Value $Content -Encoding UTF8
  Write-Host "Atualizado: $Path" -ForegroundColor Green
}

function Is-FinancePageContent($Content) {
  if ([string]::IsNullOrWhiteSpace($Content)) {
    return $false
  }

  return (
    $Content -match "Central financeira" -or
    $Content -match "relat.rio para contador" -or
    $Content -match "Exportar relat.rio IR" -or
    $Content -match "AdminFinancePage" -or
    $Content -match "Receita diária" -or
    $Content -match "Receita diaria"
  )
}

Write-Host "Aplicando v73 - separando Orders e Financeiro de vez..." -ForegroundColor Cyan

if (-not (Test-Path $OrdersPath)) {
  throw "Nao encontrei apps\web\src\app\admin\orders\page.tsx"
}

$CurrentOrdersContent = Get-Content $OrdersPath -Raw

if (Is-FinancePageContent $CurrentOrdersContent) {
  Write-Host "/admin/orders esta com tela financeira. Vou preservar ela em /admin/finance." -ForegroundColor Yellow

  if (-not (Test-Path $FinanceDir)) {
    New-Item -ItemType Directory -Path $FinanceDir -Force | Out-Null
  }

  if (Test-Path $FinancePath) {
    $FinanceBackup = "$FinancePath.bak-v73-$Stamp"
    Copy-Item $FinancePath $FinanceBackup -Force
    Write-Host "Backup do financeiro atual criado: $FinanceBackup" -ForegroundColor DarkGray
  }

  Copy-Item $OrdersPath $FinancePath -Force
  Write-Host "Tela financeira copiada de /admin/orders para /admin/finance." -ForegroundColor Green
} elseif (-not (Test-Path $FinancePath)) {
  Write-Host "/admin/orders ja parece ser pedidos, mas /admin/finance nao existe. Criando placeholder financeiro." -ForegroundColor Yellow
  Write-Utf8FileFromBase64 $FinancePath ""
} else {
  Write-Host "/admin/orders ja parece ser pedidos e /admin/finance ja existe." -ForegroundColor Green
}

Write-Host "Agora vou forcar /admin/orders como tela de pedidos." -ForegroundColor Cyan
Write-Utf8FileFromBase64 $OrdersPath ""

if (Test-Path $HeaderPath) {
  $HeaderContent = Get-Content $HeaderPath -Raw
  $OriginalHeader = $HeaderContent

  if ($HeaderContent -notmatch 'href:\s*"/admin/finance"') {
    if ($HeaderContent -match '\{\s*label:\s*"Pedidos"\s*,\s*href:\s*"/admin/orders"\s*\},') {
      $HeaderContent = [regex]::Replace(
        $HeaderContent,
        '\{\s*label:\s*"Pedidos"\s*,\s*href:\s*"/admin/orders"\s*\},',
        '{ label: "Pedidos", href: "/admin/orders" },' + "`r`n" + '    { label: "Financeiro", href: "/admin/finance" },',
        1
      )
    } else {
      Write-Host "Nao encontrei ponto exato para inserir Financeiro no header." -ForegroundColor Yellow
    }
  }

  if ($HeaderContent -ne $OriginalHeader) {
    $HeaderBackup = "$HeaderPath.bak-v73-$Stamp"
    Copy-Item $HeaderPath $HeaderBackup -Force
    Set-Content -Path $HeaderPath -Value $HeaderContent -Encoding UTF8
    Write-Host "Header atualizado com link Financeiro." -ForegroundColor Green
  } else {
    Write-Host "Header sem alteracoes." -ForegroundColor Yellow
  }
} else {
  Write-Host "CustomerHeader.tsx nao encontrado. Pulei patch do menu." -ForegroundColor Yellow
}

Write-Host ""
Write-Host "v73 aplicada com sucesso." -ForegroundColor Green
Write-Host ""
Write-Host "Confira:" -ForegroundColor Cyan
Write-Host "http://localhost:3000/admin/orders  -> pedidos" -ForegroundColor Cyan
Write-Host "http://localhost:3000/admin/finance -> financeiro" -ForegroundColor Cyan
Write-Host ""
Write-Host "Reinicie o WEB:" -ForegroundColor Cyan
Write-Host 'cd "C:\Users\march\OneDrive\Área de Trabalho\plataforma-ingressos\apps\web"' -ForegroundColor Cyan
Write-Host "npm run dev" -ForegroundColor Cyan
